import time
import hashlib
import hmac
import os
import struct
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple

# Token bucket rate limiter with configurable parameters
@dataclass
class TokenBucket:
    capacity: int
    refill_rate: int  # tokens per second
    tokens: int = 0
    last_refill: float = 0.0

    def __post_init__(self):
        self.tokens = self.capacity
        self.last_refill = time.time()

    def _refill(self) -> None:
        now = time.time()
        elapsed = now - self.last_refill
        # Calculate tokens to add based on elapsed time
        new_tokens = int(elapsed * self.refill_rate)
        self.tokens = min(self.capacity, self.tokens + new_tokens)
        self.last_refill = now

    def consume(self, count: int = 1) -> bool:
        self._refill()
        if self.tokens >= count:
            self.tokens -= count
            return True
        return False


class RateLimitConfig:
    """Parses rate limit configuration from a binary config format.
    Format: [capacity:4bytes][refill_rate:4bytes][cost_multiplier:4bytes]
    All values are unsigned 32-bit integers.
    """
    def __init__(self, config_data: bytes):
        if len(config_data) < 12:
            raise ValueError("Invalid config data")
        # Parse as unsigned 32-bit integers
        self.capacity = struct.unpack('>I', config_data[0:4])[0]
        self.refill_rate = struct.unpack('>I', config_data[4:8])[0]
        self.cost_multiplier = struct.unpack('>I', config_data[8:12])[0]

    def get_request_cost(self, payload_size: int) -> int:
        """Calculate the token cost for a request based on payload size.
        Cost = (payload_size * cost_multiplier) / 1024
        Minimum cost is 1 token.
        """
        # Use Python's arbitrary precision integers for safe arithmetic
        raw_cost = payload_size * self.cost_multiplier
        cost = raw_cost // 1024
        return max(1, cost)


class SecureAPIGateway:
    def __init__(self, config_data: bytes, secret_key: bytes):
        self.config = RateLimitConfig(config_data)
        self.secret_key = secret_key
        self.buckets: Dict[str, TokenBucket] = {}
        self.request_log: list = []

    def _get_bucket(self, client_id: str) -> TokenBucket:
        if client_id not in self.buckets:
            self.buckets[client_id] = TokenBucket(
                capacity=self.config.capacity,
                refill_rate=self.config.refill_rate
            )
        return self.buckets[client_id]

    def _verify_signature(self, client_id: str, payload: bytes, signature: bytes) -> bool:
        expected = hmac.new(self.secret_key, client_id.encode() + payload, hashlib.sha256).digest()
        return hmac.compare_digest(expected, signature)

    def _compute_cost(self, payload: bytes) -> int:
        return self.config.get_request_cost(len(payload))

    def handle_request(self, client_id: str, payload: bytes, signature: bytes) -> Tuple[bool, str]:
        """Process an API request with rate limiting and authentication."""
        # Verify request signature
        if not self._verify_signature(client_id, payload, signature):
            return (False, "authentication_failed")

        # Calculate cost and check rate limit
        cost = self._compute_cost(payload)
        bucket = self._get_bucket(client_id)

        if not bucket.consume(cost):
            self._log_event(client_id, "rate_limited", len(payload))
            return (False, "rate_limited")

        self._log_event(client_id, "allowed", len(payload))
        return (True, "ok")

    def _log_event(self, client_id: str, event: str, size: int) -> None:
        self.request_log.append({
            "client": client_id,
            "event": event,
            "size": size,
            "time": time.time()
        })


def create_default_gateway(secret_key: bytes) -> SecureAPIGateway:
    """Create gateway with default config: capacity=100, refill=10/s, multiplier=1024"""
    config = struct.pack('>III', 100, 10, 1024)
    return SecureAPIGateway(config, secret_key)


def create_gateway_from_config(config_path: str, secret_key: bytes) -> SecureAPIGateway:
    """Load gateway configuration from file."""
    with open(config_path, 'rb') as f:
        config_data = f.read(12)
    return SecureAPIGateway(config_data, secret_key)
